                const nLum = (nr + ng + nb) / 3;
                const nIsDrawing = nLum < t;
                const nIsGreen = ng > 55 && ng > nr + 14 && ng > nb + 14;
                const nIsRed = nr > 55 && nr > ng + 14 && nr > nb + 14;
                const nIsColorVar = Math.max(nr, ng, nb) - Math.min(nr, ng, nb) > 12;
